import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Dumbbell, Timer as TimerIcon, Calendar as CalendarIcon, Activity, Plus, Settings, Trash2, Edit2, Save, X, ChevronLeft, ChevronRight, Play, CheckCircle2, ChevronUp, ChevronDown, Search } from 'lucide-react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, generateId, getLocalDateString, formatDuration, MUSCLE_GROUPS, Workout, Scheduled, History, WorkoutItem, Exercise } from './db';
import { useTimer } from './TimerContext';

export function CalendarView() {
  const navigate = useNavigate();
  const [currentDate, setCurrentDate] = useState(new Date()); const [view, setView] = useState<'matrix' | 'month'>('matrix'); const [dayOffset, setDayOffset] = useState(0);
  
  const todayStr = getLocalDateString(new Date());
  const visibleDays = Array.from({ length: 5 }).map((_, i) => { const d = new Date(); d.setDate(d.getDate() + dayOffset + i - 2); return d; });
  const visibleStrs = visibleDays.map(d => getLocalDateString(d));

  const scheduledMatrix = useLiveQuery(() => db.scheduled.where('date').anyOf(visibleStrs).toArray(), [dayOffset]);
  const historyMatrix = useLiveQuery(() => db.history.where('date').anyOf(visibleStrs).toArray(), [dayOffset]);
  
  const scheduledMonth = useLiveQuery(() => db.scheduled.toArray());
  const historyMonth = useLiveQuery(() => db.history.toArray());
  const workouts = useLiveQuery(() => db.workouts.toArray());
  const exercises = useLiveQuery(() => db.exercises.toArray());

  const scheduled = view === 'matrix' ? scheduledMatrix : scheduledMonth;
  const historyData = view === 'matrix' ? historyMatrix : historyMonth;

  const [planModalDate, setPlanModalDate] = useState<string | null>(null); const [dayDetailsDate, setDayDetailsDate] = useState<string | null>(null);
  const [activePlanAction, setActivePlanAction] = useState<Scheduled | null>(null); const [activeHistoryAction, setActiveHistoryAction] = useState<History | null>(null);
  const [planSetup, setPlanSetup] = useState<{ isEditExistingId?: string; date: string; baseWorkoutId: string; editName: string; editItems: WorkoutItem[]; showAddEx: boolean; exSearch: string; } | null>(null);
  const [planNote, setPlanNote] = useState(''); const [historyEditSetup, setHistoryEditSetup] = useState<{ id: string; name: string; mm: number; ss: number; items: WorkoutItem[]; note: string; showAddEx: boolean; exSearch: string; } | null>(null);

  useEffect(() => { if (!activePlanAction) setPlanNote(''); }, [activePlanAction]);

  const getMonthDays = (year: number, month: number) => { const daysInMonth = new Date(year, month + 1, 0).getDate(); const days = []; for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i)); return days; };
  const currentYear = new Date().getFullYear(); const yearsList = Array.from({length: 8}, (_, i) => currentYear - 2 + i);

  const initiatePlanSetup = (date: string, workout: Workout) => { setPlanSetup({ isEditExistingId: undefined, date, baseWorkoutId: workout.id, editName: workout.name || '', editItems: workout.items ? workout.items.map(i => ({...i})) : [], showAddEx: false, exSearch: '' }); };
  const savePlanSetup = async () => { if (planSetup) { if (planSetup.isEditExistingId) { await db.scheduled.update(planSetup.isEditExistingId, { name: planSetup.editName, items: planSetup.editItems }); } else { await db.scheduled.add({ id: generateId(), date: planSetup.date, workoutId: planSetup.baseWorkoutId, name: planSetup.editName, items: planSetup.editItems, isCompleted: false }); } setPlanSetup(null); } };
  const startHistoryEdit = (h: History) => { setHistoryEditSetup({ id: h.id, name: h.workoutName, mm: Math.floor(h.duration / 60), ss: Math.floor(h.duration % 60), items: h.items ? h.items.map(i => ({...i})) : [], note: h.note || '', showAddEx: false, exSearch: '' }); setActiveHistoryAction(null); };
  const saveHistoryEdit = async () => { if (historyEditSetup) { const duration = (historyEditSetup.mm || 0) * 60 + (historyEditSetup.ss || 0); await db.history.update(historyEditSetup.id, { duration, items: historyEditSetup.items, note: historyEditSetup.note }); setHistoryEditSetup(null); } };
  const handlePlan = (workout: Workout) => { if (planModalDate) { initiatePlanSetup(planModalDate, workout); setPlanModalDate(null); } };
  const handleMarkDone = async (plan: Scheduled) => { const wName = plan.name || workouts?.find(w => w.id === plan.workoutId)?.name || 'Невідомо'; const rawItems = plan.items || workouts?.find(w => w.id === plan.workoutId)?.items || []; const snapItems = rawItems.map(i => { const ex = exercises?.find(e => e.id === i.exerciseId); return { ...i, exNameSnapshot: ex?.name, exMuscleSnapshot: ex?.muscle }; }); await db.history.add({ id: generateId(), date: plan.date, workoutId: plan.workoutId, workoutName: wName, duration: 0, items: snapItems, note: planNote }); await db.scheduled.delete(plan.id); setActivePlanAction(null); };
  const handleStart = (plan: Scheduled, workout: Workout) => { setActivePlanAction(null); navigate('/timer', { state: { plan, workout } }); };
  const handleCellClickMatrix = (dStr: string, workout: Workout, isPlanned: boolean, planObj?: Scheduled) => { if (isPlanned && planObj) setActivePlanAction(planObj); else initiatePlanSetup(dStr, workout); };

  const sortedWorkouts = useMemo(() => workouts?.slice().sort((a, b) => { const m1 = a.muscles?.[0] || a.muscle || 'Загальна'; const m2 = b.muscles?.[0] || b.muscle || 'Загальна'; if (m1 !== m2) return m1.localeCompare(m2, 'uk-UA'); return (a.name || '').localeCompare(b.name || '', 'uk-UA'); }), [workouts]);
  const filteredMatrixWorkouts = useMemo(() => sortedWorkouts?.filter(w => { return visibleDays.some(day => { const dStr = getLocalDateString(day); const hasHist = historyData?.some(h => h.date === dStr && (h.workoutId === w.id || h.workoutName === w.name)); const hasPlan = scheduled?.some(s => s.date === dStr && s.workoutId === w.id); return hasHist || hasPlan; }); }), [sortedWorkouts, visibleDays, historyData, scheduled]);

  return (
    <div className="p-2 pb-24">
      <div className="flex justify-between items-center mb-4 px-2"><div className="flex items-center gap-2"><span className="text-xs font-bold text-gray-400 bg-gray-100 px-2 py-1 rounded">v3.0</span><div className="flex bg-gray-200 rounded-lg p-1"><button className={`px-4 py-1 rounded-md text-sm font-bold ${view === 'matrix' ? 'bg-white shadow' : ''}`} onClick={() => setView('matrix')}>Таблиця</button><button className={`px-4 py-1 rounded-md text-sm font-bold ${view === 'month' ? 'bg-white shadow' : ''}`} onClick={() => setView('month')}>Місяць</button></div></div><button onClick={() => { setCurrentDate(new Date()); setDayOffset(0); }} className="text-blue-600 font-bold text-sm bg-blue-50 px-3 py-1 rounded">Сьогодні</button></div>

      {view === 'month' && (
        <div className="bg-white rounded-xl shadow-sm p-4 mx-2">
          <div className="flex gap-2 mb-4"><select value={currentDate.getMonth()} onChange={e => { const d = new Date(currentDate); d.setDate(1); d.setMonth(Number(e.target.value)); setCurrentDate(d); }} className="p-2 border rounded font-bold bg-gray-50 flex-1">{Array.from({length: 12}).map((_, i) => <option key={i} value={i}>{new Date(2000, i).toLocaleDateString('uk-UA', {month: 'long'})}</option>)}</select><select value={currentDate.getFullYear()} onChange={e => { const d = new Date(currentDate); d.setFullYear(Number(e.target.value)); setCurrentDate(d); }} className="p-2 border rounded font-bold bg-gray-50 w-24">{yearsList.map(y => <option key={y} value={y}>{y}</option>)}</select></div>
          <div className="grid grid-cols-7 gap-1 text-center text-xs mb-2 text-gray-500 font-bold"><div>Пн</div><div>Вт</div><div>Ср</div><div>Чт</div><div>Пт</div><div>Сб</div><div>Нд</div></div>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: (new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay() + 6) % 7 }).map((_, i) => <div key={`e-${i}`} />)}
            {getMonthDays(currentDate.getFullYear(), currentDate.getMonth()).map(day => {
              const dStr = getLocalDateString(day); const plans = scheduled?.filter(s => s.date === dStr) || []; const hists = historyData?.filter(h => h.date === dStr) || [];
              let bgClass = 'bg-white border-transparent'; let textClass = 'text-gray-700'; let content = null;
              if (hists.length > 0) { const w = workouts?.find(w => w.id === hists[0].workoutId || w.name === hists[0].workoutName); const wMuscles = w?.muscles?.length ? w.muscles : (w?.muscle ? [w.muscle] : ['Загальна']); bgClass = 'bg-green-100 border-green-300 shadow-sm'; textClass = 'text-green-800 font-bold'; content = (<div className="flex flex-col items-center mt-1 px-0.5 w-full"><span className="text-[9px] leading-none text-center opacity-90 break-words">{wMuscles.join(', ')}</span><span className="text-[9px] mt-1 font-mono opacity-80">{formatDuration(hists[0].duration)}</span></div>); } else if (plans.length > 0) { const w = workouts?.find(w => w.id === plans[0].workoutId); const wMuscles = w?.muscles?.length ? w.muscles : (w?.muscle ? [w.muscle] : ['Загальна']); bgClass = 'bg-white border-blue-300 shadow-md ring-1 ring-blue-100'; textClass = 'text-gray-900 font-bold'; content = (<div className="flex flex-col items-center mt-1 px-0.5 w-full"><span className="text-[9px] text-blue-600 leading-none text-center break-words">{wMuscles.join(', ')}</span><span className="text-[9px] mt-1 font-mono text-gray-400">--:--</span></div>); }
              return (<div key={dStr} onClick={() => setDayDetailsDate(dStr)} className={`min-h-[70px] flex flex-col items-center pt-1 pb-1 rounded-md text-sm cursor-pointer border relative ${bgClass} ${textClass} ${dStr === todayStr ? 'ring-2 ring-blue-500' : ''}`}><span className="text-[10px] opacity-70 leading-none mb-1">{day.getDate()}</span>{content}</div>);
            })}
          </div>
        </div>
      )}

      {view === 'matrix' && (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-x-auto relative">
          <table className="w-full text-left border-collapse min-w-max">
            <thead>
              <tr>
                <th className="sticky left-0 bg-white z-10 p-2 border-b border-r min-w-[100px] max-w-[120px]"><div className="flex justify-between items-center bg-gray-100 rounded-md p-1"><button onClick={() => setDayOffset(d => d - 1)} className="p-1 bg-white rounded shadow-sm text-gray-600 active:bg-gray-200"><ChevronLeft size={16}/></button><span className="text-[9px] font-bold text-gray-500">ПЕРІОД</span><button onClick={() => setDayOffset(d => d + 1)} className="p-1 bg-white rounded shadow-sm text-gray-600 active:bg-gray-200"><ChevronRight size={16}/></button></div></th>
                {visibleDays.map(day => {
                  const dStr = getLocalDateString(day); const isToday = dStr === todayStr;
                  return (<th key={dStr} className={`p-2 border-b text-center min-w-[65px] ${isToday ? 'bg-blue-50' : ''}`}><div className={`text-[10px] uppercase ${isToday ? 'text-blue-600 font-bold' : 'text-gray-400'}`}>{day.toLocaleDateString('uk-UA', { weekday: 'short' })}</div><div className={`text-sm font-bold ${isToday ? 'text-blue-700' : 'text-gray-800'}`}>{day.getDate()}.{(day.getMonth() + 1).toString().padStart(2, '0')}</div><button onClick={() => setPlanModalDate(dStr)} className="mt-1.5 flex items-center justify-center w-8 h-8 mx-auto bg-blue-100 text-blue-700 rounded-full hover:bg-blue-200 shadow-sm transition-colors"><Plus size={18} /></button></th>);
                })}
              </tr>
            </thead>
            <tbody>
              {filteredMatrixWorkouts?.length === 0 && (<tr><td colSpan={6} className="text-center p-6 text-gray-400 text-sm">В цьому періоді немає тренувань. Натисніть синій "+" на даті, щоб додати.</td></tr>)}
              {filteredMatrixWorkouts?.map(w => {
                const wMusclesStr = w.muscles?.length ? w.muscles.join(', ') : (w.muscle || 'Загальна');
                return (
                  <tr key={w.id} className="hover:bg-gray-50">
                    <td className="sticky left-0 bg-white z-10 p-2 border-b border-r max-w-[120px]" style={{ whiteSpace: 'normal', wordBreak: 'break-word' }}><div className="text-[10px] font-bold text-gray-400 uppercase mb-0.5">{wMusclesStr}</div><div className="text-[11px] font-bold text-gray-800 leading-tight">{w.name}</div></td>
                    {visibleDays.map(day => {
                      const dStr = getLocalDateString(day); const isToday = dStr === todayStr;
                      const hist = historyData?.find(h => h.date === dStr && (h.workoutId === w.id || h.workoutName === w.name));
                      const plan = scheduled?.find(s => s.date === dStr && s.workoutId === w.id);
                      const firstLetter = (plan?.name || w.name || '?').charAt(0).toUpperCase();
                      return (<td key={dStr} className={`p-1 border-b text-center align-middle border-l border-gray-100 ${isToday && !hist ? 'bg-blue-50/50' : ''}`}>
                          {hist ? (<div onClick={() => setActiveHistoryAction(hist)} className="bg-green-100 text-green-800 rounded shadow-sm flex flex-col items-center justify-center cursor-pointer hover:bg-green-200 w-full h-14 border border-green-200"><span className="text-xl font-black leading-none">{firstLetter}</span><span className="text-[9px] mt-1 font-mono">{formatDuration(hist.duration)}</span></div>) : plan ? (<button onClick={() => handleCellClickMatrix(dStr, w, true, plan)} className="bg-blue-500 text-white rounded w-full h-14 shadow-sm active:bg-blue-600 flex flex-col items-center justify-center"><span className="text-xl font-black leading-none">{firstLetter}</span><span className="text-[9px] mt-1 font-mono text-blue-200">--:--</span></button>) : (<div onClick={() => handleCellClickMatrix(dStr, w, false)} className="h-14 w-full rounded flex items-center justify-center hover:bg-gray-100 cursor-pointer text-gray-300 hover:text-gray-400"><Plus size={18} /></div>)}
                        </td>);
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {historyEditSetup && (
        <div className="fixed inset-0 bg-black/60 flex items-end justify-center z-[110] p-2 pb-16"><div className="bg-white w-full max-w-md rounded-2xl p-5 shadow-2xl max-h-[90vh] flex flex-col relative"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold text-lg">Редагування історії</h3><button onClick={() => setHistoryEditSetup(null)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="flex gap-4 mb-4"><div className="flex-1"><label className="text-[10px] text-gray-500 font-bold uppercase">Хвилини</label><input type="number" inputMode="decimal" value={historyEditSetup.mm} onChange={e => setHistoryEditSetup({...historyEditSetup, mm: Number(e.target.value)})} className="w-full p-3 border rounded-lg bg-gray-50 font-bold text-center" /></div><div className="flex-1"><label className="text-[10px] text-gray-500 font-bold uppercase">Секунди</label><input type="number" inputMode="decimal" value={historyEditSetup.ss} onChange={e => setHistoryEditSetup({...historyEditSetup, ss: Number(e.target.value)})} className="w-full p-3 border rounded-lg bg-gray-50 font-bold text-center" /></div></div><div className="flex-1 overflow-y-auto space-y-3 mb-4">{historyEditSetup.items.map((item, idx) => { const exName = exercises?.find(e => e.id === item.exerciseId)?.name || item.exNameSnapshot || 'Вправа'; return (<div key={idx} className="p-3 bg-white border rounded-xl shadow-sm relative"><div className="flex justify-between items-center mb-2"><span className="font-bold text-sm text-blue-800">{exName}</span><button onClick={() => { const n = historyEditSetup.items.map(i=>({...i})); n.splice(idx, 1); setHistoryEditSetup({...historyEditSetup, items: n}); }} className="p-2 text-red-400"><Trash2 size={16}/></button></div><div className="grid grid-cols-3 gap-2"><div><label className="text-[9px] text-gray-400 uppercase font-bold">Вага</label><input inputMode="decimal" value={item.weight} onChange={e => { const n = historyEditSetup.items.map(i=>({...i})); n[idx].weight = e.target.value; setHistoryEditSetup({...historyEditSetup, items: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div><div><label className="text-[9px] text-gray-400 uppercase font-bold">Еспандер</label><input value={item.band} onChange={e => { const n = historyEditSetup.items.map(i=>({...i})); n[idx].band = e.target.value; setHistoryEditSetup({...historyEditSetup, items: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div><div><label className="text-[9px] text-gray-400 uppercase font-bold">Повтори</label><input inputMode="decimal" value={item.reps} onChange={e => { const n = historyEditSetup.items.map(i=>({...i})); n[idx].reps = e.target.value; setHistoryEditSetup({...historyEditSetup, items: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div></div></div>); })}<button onClick={() => setHistoryEditSetup({...historyEditSetup, showAddEx: true, exSearch: ''})} className="w-full py-3 bg-blue-50 text-blue-600 rounded-lg font-bold border border-dashed border-blue-300 flex justify-center items-center gap-2"><Plus size={18}/> Додати вправу</button></div><textarea value={historyEditSetup.note} onChange={e => setHistoryEditSetup({...historyEditSetup, note: e.target.value})} placeholder="Примітка до тренування..." className="w-full p-3 border rounded-lg bg-gray-50 text-sm shadow-sm min-h-[60px] mb-4" /><div className="flex gap-3 mt-auto shrink-0"><button onClick={() => setHistoryEditSetup(null)} className="flex-1 bg-gray-100 text-gray-700 py-3 rounded-lg font-bold">Скасувати</button><button onClick={saveHistoryEdit} className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-bold flex justify-center items-center gap-2"><Save size={18}/> Зберегти зміни</button></div>{historyEditSetup.showAddEx && (<div className="absolute inset-0 bg-white rounded-2xl flex flex-col p-4 z-20"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold">Оберіть вправу</h3><button onClick={() => setHistoryEditSetup({...historyEditSetup, showAddEx: false})} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="relative mb-3"><Search className="absolute left-3 top-3 text-gray-400" size={18} /><input value={historyEditSetup.exSearch} onChange={e => setHistoryEditSetup({...historyEditSetup, exSearch: e.target.value})} placeholder="Пошук..." className="w-full p-2 pl-10 border rounded-lg bg-gray-50" /></div><div className="flex-1 overflow-y-auto space-y-2">{historyEditSetup.exSearch.trim() && !exercises?.some(e => e.name.toLowerCase() === historyEditSetup.exSearch.trim().toLowerCase()) && (<button onClick={async () => { const newId = generateId(); await db.exercises.add({ id: newId, name: historyEditSetup.exSearch.trim(), category: 'Користувацькі', muscle: 'Загальна' }); setHistoryEditSetup({ ...historyEditSetup, items: [...historyEditSetup.items, { exerciseId: newId, weight: '', band: '', reps: '', note: '' }], showAddEx: false, exSearch: '' }); }} className="w-full text-left p-3 bg-blue-50 text-blue-700 border border-blue-200 rounded font-bold mb-2">+ Створити: "{historyEditSetup.exSearch.trim()}"</button>)}{exercises?.filter(ex => ex.name.toLowerCase().includes(historyEditSetup.exSearch.toLowerCase())).map(ex => (<button key={ex.id} onClick={() => { setHistoryEditSetup({ ...historyEditSetup, items: [...historyEditSetup.items, { exerciseId: ex.id, weight: '', band: '', reps: '', note: '' }], showAddEx: false }); }} className="w-full text-left p-3 bg-gray-50 border rounded font-medium">{ex.name}</button>))}</div></div>)}</div></div>
      )}

      {planSetup && (
        <div className="fixed inset-0 bg-black/60 flex items-end justify-center z-[110] p-2 pb-16"><div className="bg-white w-full max-w-md rounded-2xl p-5 shadow-2xl max-h-[90vh] flex flex-col relative"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold text-lg">План на {planSetup.date}</h3><button onClick={() => setPlanSetup(null)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><input value={planSetup.editName} onChange={e => setPlanSetup({...planSetup, editName: e.target.value})} placeholder="Назва плану" className="w-full p-3 border rounded-lg mb-4 font-bold bg-gray-50" /><div className="flex-1 overflow-y-auto space-y-3 mb-4">{planSetup.editItems.map((item, idx) => { const exName = exercises?.find(e => e.id === item.exerciseId)?.name || 'Вправа'; return (<div key={idx} className="p-3 bg-white border rounded-xl shadow-sm relative"><div className="flex justify-between items-center mb-2"><span className="font-bold text-sm text-blue-800">{exName}</span><button onClick={() => { const n = planSetup.editItems.map(i=>({...i})); n.splice(idx, 1); setPlanSetup({...planSetup, editItems: n}); }} className="p-2 text-red-400"><Trash2 size={16}/></button></div><div className="grid grid-cols-3 gap-2"><div><label className="text-[9px] text-gray-400 uppercase font-bold">Вага</label><input inputMode="decimal" value={item.weight} onChange={e => { const n = planSetup.editItems.map(i=>({...i})); n[idx].weight = e.target.value; setPlanSetup({...planSetup, editItems: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div><div><label className="text-[9px] text-gray-400 uppercase font-bold">Еспандер</label><input value={item.band} onChange={e => { const n = planSetup.editItems.map(i=>({...i})); n[idx].band = e.target.value; setPlanSetup({...planSetup, editItems: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div><div><label className="text-[9px] text-gray-400 uppercase font-bold">Повтори</label><input inputMode="decimal" value={item.reps} onChange={e => { const n = planSetup.editItems.map(i=>({...i})); n[idx].reps = e.target.value; setPlanSetup({...planSetup, editItems: n}); }} className="w-full p-2 border rounded text-xs bg-gray-50" /></div></div></div>); })}<button onClick={() => setPlanSetup({...planSetup, showAddEx: true, exSearch: ''})} className="w-full py-3 bg-blue-50 text-blue-600 rounded-lg font-bold border border-dashed border-blue-300 flex justify-center items-center gap-2"><Plus size={18}/> Додати вправу</button></div><div className="flex gap-3 mt-auto shrink-0"><button onClick={() => setPlanSetup(null)} className="flex-1 bg-gray-100 text-gray-700 py-3 rounded-lg font-bold">Скасувати</button><button onClick={savePlanSetup} className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-bold flex justify-center items-center gap-2"><Save size={18}/> Зберегти план</button></div>{planSetup.showAddEx && (<div className="absolute inset-0 bg-white rounded-2xl flex flex-col p-4 z-20"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold">Оберіть вправу</h3><button onClick={() => setPlanSetup({...planSetup, showAddEx: false})} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="relative mb-3"><Search className="absolute left-3 top-3 text-gray-400" size={18} /><input value={planSetup.exSearch} onChange={e => setPlanSetup({...planSetup, exSearch: e.target.value})} placeholder="Пошук..." className="w-full p-2 pl-10 border rounded-lg bg-gray-50" /></div><div className="flex-1 overflow-y-auto space-y-2">{planSetup.exSearch.trim() && !exercises?.some(e => e.name.toLowerCase() === planSetup.exSearch.trim().toLowerCase()) && (<button onClick={async () => { const newId = generateId(); await db.exercises.add({ id: newId, name: planSetup.exSearch.trim(), category: 'Користувацькі', muscle: 'Загальна' }); setPlanSetup({ ...planSetup, editItems: [...planSetup.editItems, { exerciseId: newId, weight: '', band: '', reps: '', note: '' }], showAddEx: false, exSearch: '' }); }} className="w-full text-left p-3 bg-blue-50 text-blue-700 border border-blue-200 rounded font-bold mb-2">+ Створити: "{planSetup.exSearch.trim()}"</button>)}{exercises?.filter(ex => ex.name.toLowerCase().includes(planSetup.exSearch.toLowerCase())).map(ex => (<button key={ex.id} onClick={() => { setPlanSetup({ ...planSetup, editItems: [...planSetup.editItems, { exerciseId: ex.id, weight: '', band: '', reps: '', note: '' }], showAddEx: false }); }} className="w-full text-left p-3 bg-gray-50 border rounded font-medium">{ex.name}</button>))}</div></div>)}</div></div>
      )}

      {planModalDate && (
        <div className="fixed inset-0 bg-black/50 flex items-end z-[100] pb-20"><div className="bg-white w-full rounded-t-2xl p-4 max-h-[70vh] overflow-y-auto"><div className="flex justify-between items-center mb-4"><h3 className="font-bold text-lg">Вибір шаблону</h3><button onClick={() => setPlanModalDate(null)} className="p-2 text-red-500 bg-red-50 rounded-full"><X size={20}/></button></div><div className="space-y-2"><button onClick={() => handlePlan({ id: generateId(), name: '', items: [], note: '', muscle: 'Загальна' })} className="w-full text-center p-4 bg-blue-50 text-blue-600 rounded-xl font-bold border border-blue-200 border-dashed shadow-sm mb-2">+ Створити порожнє</button>{workouts?.slice().sort((a, b) => (a.name || '').localeCompare(b.name || '', 'uk-UA')).map(w => (<button key={w.id} onClick={() => handlePlan(w)} className="w-full text-left p-4 bg-gray-50 rounded-xl font-bold border active:bg-gray-200 shadow-sm">{w.name}</button>))}</div></div></div>
      )}

      {dayDetailsDate && (
        <div className="fixed inset-0 bg-black/50 flex items-end z-[100] pb-20"><div className="bg-white w-full rounded-t-2xl p-4 max-h-[80vh] overflow-y-auto"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold text-lg">Деталі за {dayDetailsDate}</h3><button onClick={() => setDayDetailsDate(null)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div>{historyData?.filter(h => h.date === dayDetailsDate).map(h => (<div key={h.id} className="mb-4 p-4 bg-green-50 border border-green-200 rounded-xl relative"><div className="flex justify-between items-center mb-2"><span className="font-bold text-green-800 text-lg">✓ {h.workoutName}</span><span className="text-sm font-mono bg-green-100 text-green-800 px-2 py-1 rounded">{formatDuration(h.duration)}</span></div><div className="flex gap-2 mt-3"><button onClick={() => { setDayDetailsDate(null); startHistoryEdit(h); }} className="flex-1 bg-white border border-green-300 text-green-700 p-2 rounded-lg font-bold flex justify-center items-center gap-2"><Edit2 size={16}/> Редагувати</button><button onClick={() => { if(window.confirm('Видалити запис історії?')) db.history.delete(h.id); }} className="flex-1 bg-red-100 text-red-600 p-2 rounded-lg font-bold flex justify-center items-center gap-2"><Trash2 size={16}/> Видалити</button></div></div>))}{scheduled?.filter(s => s.date === dayDetailsDate).map(p => { const w = workouts?.find(x => x.id === p.workoutId); const displayName = p.name || w?.name || 'Видалене'; return (<div key={p.id} className="mb-4 p-4 bg-gray-50 border border-gray-200 rounded-xl"><div className="font-bold text-gray-800 mb-3 text-lg">ПЛАН: {displayName}</div><div className="grid grid-cols-2 gap-2"><button onClick={() => { setDayDetailsDate(null); if (w) handleStart(p, w); }} className="bg-blue-500 text-white p-3 rounded-lg font-bold text-xs flex justify-center items-center gap-1"><Play size={16}/> СТАРТ</button><button onClick={() => { setDayDetailsDate(null); setActivePlanAction(p); }} className="bg-gray-200 text-gray-800 p-3 rounded-lg font-bold text-xs flex justify-center items-center gap-1"><CheckCircle2 size={16}/> ВІДМІТИТИ</button><button onClick={() => { setDayDetailsDate(null); setPlanSetup({ isEditExistingId: p.id, date: p.date, baseWorkoutId: p.workoutId, editName: p.name || w?.name || '', editItems: p.items ? p.items.map(i=>({...i})) : (w?.items ? w.items.map(i=>({...i})) : []), showAddEx: false, exSearch: '' }); }} className="bg-white border border-gray-300 text-gray-700 p-3 rounded-lg font-bold text-xs flex justify-center items-center gap-1"><Edit2 size={16}/> РЕДАГУВАТИ</button><button onClick={() => { if(window.confirm('Видалити цей план?')) db.scheduled.delete(p.id); }} className="bg-red-50 text-red-500 p-3 rounded-lg font-bold text-xs flex justify-center items-center gap-1"><Trash2 size={16}/> ВИДАЛИТИ</button></div></div>); })}<button onClick={() => { setPlanModalDate(dayDetailsDate); setDayDetailsDate(null); }} className="w-full mt-2 p-3 bg-blue-50 text-blue-600 rounded-lg font-bold border border-dashed border-blue-300">+ Додати план</button></div></div>
      )}

      {activePlanAction && (
        <div className="fixed inset-0 bg-black/50 flex items-end z-[100] pb-20"><div className="bg-white w-full rounded-t-2xl p-4"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold text-lg text-gray-800">Дія з планом</h3><button onClick={() => setActivePlanAction(null)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="space-y-3"><button onClick={() => { const w = workouts?.find(x => x.id === activePlanAction.workoutId); if (w) handleStart(activePlanAction, w); }} className="w-full bg-blue-600 text-white p-4 rounded-xl font-bold flex items-center justify-center gap-2 shadow-sm"><Play size={20} /> Почати (Таймер)</button><button onClick={() => { const w = workouts?.find(x => x.id === activePlanAction.workoutId); setPlanSetup({ isEditExistingId: activePlanAction.id, date: activePlanAction.date, baseWorkoutId: activePlanAction.workoutId, editName: activePlanAction.name || w?.name || '', editItems: activePlanAction.items ? activePlanAction.items.map(i=>({...i})) : (w?.items ? w.items.map(i=>({...i})) : []), showAddEx: false, exSearch: '' }); setActivePlanAction(null); }} className="w-full bg-white border border-gray-300 text-gray-700 p-4 rounded-xl font-bold flex items-center justify-center gap-2 shadow-sm"><Edit2 size={20} /> Редагувати план</button><div className="bg-gray-50 p-3 rounded-xl border border-gray-200 mt-4"><textarea value={planNote} onChange={e => setPlanNote(e.target.value)} placeholder="Додати примітку..." className="w-full p-3 border rounded-lg mb-3 bg-white text-sm shadow-sm min-h-[80px]" /><button onClick={() => handleMarkDone(activePlanAction)} className="w-full bg-gray-200 text-gray-800 p-3 rounded-lg font-bold flex items-center justify-center gap-2"><CheckCircle2 size={18} /> Відмітити ВИКОНАНО</button></div><button onClick={async () => { if(window.confirm('Видалити цей план?')) { await db.scheduled.delete(activePlanAction.id); setActivePlanAction(null); } }} className="w-full bg-red-50 text-red-600 p-3 rounded-xl font-bold flex items-center justify-center gap-2 mt-4"><Trash2 size={18} /> Видалити план</button></div></div></div>
      )}

      {activeHistoryAction && (
        <div className="fixed inset-0 bg-black/50 flex items-end z-[100] pb-20"><div className="bg-white w-full rounded-t-2xl p-4"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold text-lg text-green-800 flex items-center gap-2"><CheckCircle2/> {activeHistoryAction.workoutName}</h3><button onClick={() => setActiveHistoryAction(null)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="mb-4"><div className="text-xs text-gray-500 font-bold mb-1 uppercase">Час виконання</div><div className="text-3xl font-mono text-gray-800">{formatDuration(activeHistoryAction.duration)}</div></div>{activeHistoryAction.note && <div className="mb-6 bg-gray-50 p-3 rounded-xl border border-gray-100"><div className="text-xs text-gray-500 font-bold mb-1 uppercase">Примітка</div><div className="text-sm text-gray-800 whitespace-pre-wrap">{activeHistoryAction.note}</div></div>}<button onClick={() => startHistoryEdit(activeHistoryAction)} className="w-full bg-white border border-gray-300 text-gray-700 p-4 rounded-xl font-bold flex items-center justify-center gap-2 mb-3 shadow-sm"><Edit2 size={20} /> Редагувати запис</button><button onClick={() => { if(window.confirm('Видалити з історії?')) { db.history.delete(activeHistoryAction.id); setActiveHistoryAction(null); } }} className="w-full bg-red-100 text-red-600 p-4 rounded-xl font-bold flex items-center justify-center gap-2"><Trash2 size={20} /> Видалити з історії</button></div></div>
      )}
    </div>
  );
}

export function Workouts() {
  const workouts = useLiveQuery(() => db.workouts.toArray()); const exercises = useLiveQuery(() => db.exercises.toArray());
  const [editingId, setEditingId] = useState<string | null>(null); const [name, setName] = useState(''); const [muscles, setMuscles] = useState<string[]>([]); const [items, setItems] = useState<WorkoutItem[]>([]); const [showAddEx, setShowAddEx] = useState(false); const [exSearch, setExSearch] = useState('');

  const startEdit = (w: Workout | null) => { if (w) { setEditingId(w.id); setName(w.name || ''); setMuscles(w.muscles?.length ? w.muscles : (w.muscle ? [w.muscle] : ['Загальна'])); setItems(w.items ? w.items.map(i=>({...i})) : []); } else { setEditingId('new'); setName(''); setMuscles(['Загальна']); setItems([]); } };
  const saveWorkout = async () => { if (!name.trim()) return; const data = { name, muscles, items, note: '' }; if (editingId === 'new') await db.workouts.add({ id: generateId(), ...data }); else if (editingId) await db.workouts.update(editingId, data); setEditingId(null); };
  const updateItem = (index: number, field: keyof WorkoutItem, value: string) => { const newItems = items.map(i=>({...i})); newItems[index] = { ...newItems[index], [field]: value }; setItems(newItems); };
  const moveItemUp = (index: number) => { if (index === 0) return; const newItems = items.map(i=>({...i})); [newItems[index - 1], newItems[index]] = [newItems[index], newItems[index - 1]]; setItems(newItems); };
  const moveItemDown = (index: number) => { if (index === items.length - 1) return; const newItems = items.map(i=>({...i})); [newItems[index + 1], newItems[index]] = [newItems[index], newItems[index + 1]]; setItems(newItems); };

  if (editingId) {
    const filteredExs = exercises?.filter(ex => ex.name.toLowerCase().includes(exSearch.toLowerCase()) || (ex.muscle && ex.muscle.toLowerCase().includes(exSearch.toLowerCase()))).sort((a, b) => a.name.localeCompare(b.name, 'uk-UA')) || [];
    return (
      <div className="p-4 pb-24"><div className="flex justify-between items-center mb-4"><button onClick={() => setEditingId(null)} className="text-gray-500 font-bold p-2">Скасувати</button><button onClick={saveWorkout} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex gap-2"><Save size={20}/> Зберегти</button></div><input value={name} onChange={e => setName(e.target.value)} placeholder="Назва тренування" className="w-full p-3 border rounded-lg mb-4 font-bold text-lg shadow-sm" /><div className="mb-6"><label className="text-xs font-bold text-gray-500 mb-2 block uppercase">Групи м'язів</label><div className="flex flex-wrap gap-2">{MUSCLE_GROUPS.map(m => (<label key={m} className={`flex items-center gap-2 border px-3 py-2 rounded-lg text-sm shadow-sm transition-colors ${muscles.includes(m) ? 'bg-blue-50 border-blue-300 text-blue-700 font-bold' : 'bg-white text-gray-700'}`}><input type="checkbox" className="w-4 h-4" checked={muscles.includes(m)} onChange={e => { if(e.target.checked) setMuscles([...muscles, m]); else setMuscles(muscles.filter(x => x !== m)); }} />{m}</label>))}</div></div><div className="space-y-4 mb-6">{items.map((item, idx) => { const ex = exercises?.find(e => e.id === item.exerciseId); return (<div key={idx} className="bg-white p-3 rounded-lg shadow-sm border border-gray-200"><div className="flex justify-between items-start mb-3"><div><div className="font-bold text-blue-800 leading-tight pr-2">{ex?.name || 'Вправа'}</div><div className="text-[10px] text-gray-400 font-bold uppercase">{ex?.muscle || 'Загальна'}</div></div><div className="flex gap-1 shrink-0"><button onClick={() => moveItemUp(idx)} disabled={idx === 0} className="p-2 text-gray-500 bg-gray-100 rounded"><ChevronUp size={18}/></button><button onClick={() => moveItemDown(idx)} disabled={idx === items.length - 1} className="p-2 text-gray-500 bg-gray-100 rounded"><ChevronDown size={18}/></button><button onClick={() => setItems(items.filter((_, i) => i !== idx))} className="text-red-500 bg-red-50 p-2 rounded ml-2"><Trash2 size={18}/></button></div></div><div className="grid grid-cols-3 gap-2"><div><label className="text-[10px] text-gray-500 font-bold uppercase">Вага</label><input inputMode="decimal" value={item.weight} onChange={e => updateItem(idx, 'weight', e.target.value)} className="w-full p-2 border rounded text-sm bg-gray-50" /></div><div><label className="text-[10px] text-gray-500 font-bold uppercase">Еспандер</label><input value={item.band} onChange={e => updateItem(idx, 'band', e.target.value)} className="w-full p-2 border rounded text-sm bg-gray-50" /></div><div><label className="text-[10px] text-gray-500 font-bold uppercase">Повтори</label><input inputMode="decimal" value={item.reps} onChange={e => updateItem(idx, 'reps', e.target.value)} className="w-full p-2 border rounded text-sm bg-gray-50" /></div></div></div>); })}</div><button onClick={() => { setShowAddEx(true); setExSearch(''); }} className="w-full bg-blue-50 text-blue-600 py-3 rounded-lg font-bold border border-dashed border-blue-300 flex items-center justify-center gap-2"><Plus size={20} /> Додати вправу</button>{showAddEx && (<div className="fixed inset-0 bg-black/50 flex items-end z-[100] pb-20"><div className="bg-white w-full rounded-t-2xl p-4 h-[80vh] flex flex-col relative"><div className="flex justify-between items-center mb-4 border-b pb-2 shrink-0"><h3 className="font-bold text-lg">Оберіть вправу</h3><button onClick={() => setShowAddEx(false)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="mb-3 shrink-0 relative"><Search className="absolute left-3 top-3 text-gray-400" size={18} /><input value={exSearch} onChange={e => setExSearch(e.target.value)} placeholder="Пошук..." className="w-full p-2 pl-10 border rounded-lg shadow-sm bg-gray-50" /></div><div className="flex-1 overflow-y-auto space-y-2">{exSearch.trim() && !exercises?.some(e => e.name.toLowerCase() === exSearch.trim().toLowerCase()) && (<button onClick={async () => { const newId = generateId(); await db.exercises.add({ id: newId, name: exSearch.trim(), category: 'Користувацькі', muscle: 'Загальна' }); setItems([...items, { exerciseId: newId, weight: '', band: '', reps: '', note: '' }]); setShowAddEx(false); setExSearch(''); }} className="w-full text-left p-3 bg-blue-50 text-blue-700 border border-blue-200 rounded font-bold mb-2">+ Створити: "{exSearch.trim()}"</button>)}{filteredExs.map(ex => (<button key={ex.id} onClick={() => { setItems([...items, { exerciseId: ex.id, weight: '', band: '', reps: '', note: '' }]); setShowAddEx(false); }} className="w-full text-left p-3 bg-gray-50 border rounded font-medium active:bg-gray-200 flex justify-between items-center"><span>{ex.name}</span><span className="text-[10px] text-gray-400 uppercase font-bold">{ex.muscle || 'Загальна'}</span></button>))}</div></div></div>)}</div>
    );
  }

  const sortedWorkouts = workouts?.slice().sort((a, b) => { const m1 = a.muscles?.[0] || a.muscle || 'Загальна'; const m2 = b.muscles?.[0] || b.muscle || 'Загальна'; if (m1 !== m2) return m1.localeCompare(m2, 'uk-UA'); return (a.name || '').localeCompare(b.name || '', 'uk-UA'); });
  return (
    <div className="p-4 pb-24"><div className="flex justify-between items-center mb-6"><h2 className="text-2xl font-bold">Шаблони тренувань</h2><button onClick={() => startEdit(null)} className="bg-blue-600 text-white p-2 rounded-lg shadow-sm"><Plus /></button></div><div className="space-y-4">{sortedWorkouts?.map(w => { const wMusclesStr = w.muscles?.length ? w.muscles.join(', ') : (w.muscle || 'Загальна'); return (<div key={w.id} className="bg-white p-4 rounded-xl shadow-sm border border-gray-100"><div className="flex justify-between items-start mb-3"><div><div className="text-[10px] font-bold text-gray-400 uppercase mb-0.5">{wMusclesStr}</div><h3 className="font-bold text-lg text-blue-800">{w.name}</h3></div><div className="flex gap-2 mt-1"><button onClick={() => startEdit(w)} className="p-2 text-gray-400"><Edit2 size={18}/></button><button onClick={() => { if(window.confirm('Видалити шаблон?')) db.workouts.delete(w.id); }} className="p-2 text-red-400 bg-red-50 rounded"><Trash2 size={18}/></button></div></div><div className="text-sm text-gray-600 space-y-1 mt-2">{w.items?.map((item, i) => { const exName = exercises?.find(e => e.id === item.exerciseId)?.name || 'Видалена вправа'; return (<div key={i} className="flex justify-between border-b border-gray-50 pb-1"><span>{exName}</span><span className="text-xs text-gray-400 font-mono">[{item.weight || '-'} | {item.reps || '-'}]</span></div>); })}</div></div>); })}</div></div>
  );
}

export function Exercises() {
  const exercises = useLiveQuery(() => db.exercises.toArray());
  const [search, setSearch] = useState(''); const [modalOpen, setModalOpen] = useState(false); const [editId, setEditId] = useState<string | null>(null); const [formName, setFormName] = useState(''); const [formMuscle, setFormMuscle] = useState('Загальна');

  const openForm = (ex?: Exercise) => { if (ex) { setEditId(ex.id); setFormName(ex.name); setFormMuscle(ex.muscle || 'Загальна'); } else { setEditId(null); setFormName(''); setFormMuscle('Загальна'); } setModalOpen(true); };
  const saveExercise = async () => { if (!formName.trim()) return; if (editId) await db.exercises.update(editId, { name: formName, muscle: formMuscle }); else await db.exercises.add({ id: generateId(), name: formName, category: 'Користувацькі', muscle: formMuscle }); setModalOpen(false); };
  const filtered = exercises?.filter(ex => ex.name.toLowerCase().includes(search.toLowerCase()) || (ex.muscle && ex.muscle.toLowerCase().includes(search.toLowerCase()))).sort((a, b) => a.name.localeCompare(b.name, 'uk-UA')) || [];

  return (
    <div className="p-4 pb-24"><div className="flex justify-between items-center mb-4"><h2 className="text-2xl font-bold">Довідник вправ</h2><button onClick={() => openForm()} className="bg-blue-600 text-white p-2 rounded-lg shadow-sm"><Plus /></button></div><div className="relative mb-4"><Search className="absolute left-3 top-3 text-gray-400" size={18} /><input className="w-full p-2 pl-10 border rounded-lg shadow-sm bg-gray-50" placeholder="Пошук..." value={search} onChange={e => setSearch(e.target.value)} /></div><div className="space-y-2">{filtered.map(ex => (<div key={ex.id} className="bg-white p-3 rounded-lg shadow-sm border-l-4 border-blue-500 flex justify-between items-center"><div><div className="font-medium text-gray-800">{ex.name}</div><div className="text-[10px] font-bold text-gray-400 uppercase mt-0.5">{ex.muscle || 'Загальна'}</div></div><div className="flex gap-2"><button onClick={() => openForm(ex)} className="p-2 text-gray-400"><Edit2 size={16}/></button><button onClick={() => { if(window.confirm('Видалити вправу?')) db.exercises.delete(ex.id); }} className="p-2 text-red-400 bg-red-50 rounded"><Trash2 size={16}/></button></div></div>))}</div>{modalOpen && (<div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4"><div className="bg-white w-full max-w-sm rounded-xl p-5 shadow-xl relative"><h3 className="font-bold text-lg mb-4">{editId ? 'Редагувати вправу' : 'Нова вправа'}</h3><input value={formName} onChange={e => setFormName(e.target.value)} placeholder="Назва" className="w-full p-3 border rounded-lg mb-3 shadow-sm" /><select value={formMuscle} onChange={e => setFormMuscle(e.target.value)} className="w-full p-3 border rounded-lg mb-6 shadow-sm bg-white">{MUSCLE_GROUPS.map(m => <option key={m} value={m}>{m}</option>)}</select><div className="flex gap-3"><button onClick={() => setModalOpen(false)} className="flex-1 bg-gray-100 text-gray-700 py-3 rounded-lg font-bold">Скасувати</button><button onClick={saveExercise} className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-bold shadow-sm">Зберегти</button></div></div></div>)}</div>
  );
}

function NumberControl({ label, value, setValue }: { label: string, value: number | '', setValue: (v: number | '' | ((prev: number | '') => number | '')) => void }) {
  return (<div className="flex items-center justify-between w-full py-2 border-b border-gray-100 last:border-0"><div className="text-sm text-gray-500 font-bold uppercase">{label}</div><div className="flex items-center gap-2"><button onClick={() => setValue(v => Math.max(1, typeof v === 'number' ? v - 1 : (Number(v) || 1)))} className="w-12 h-12 flex items-center justify-center bg-gray-100 rounded-xl text-2xl font-bold text-gray-600 shadow-sm">-</button><input type="number" inputMode="decimal" value={value} onChange={e => { const val = e.target.value; setValue(val === '' ? '' : Math.max(1, Number(val))); }} className="w-16 text-center font-bold text-xl bg-transparent outline-none p-0 m-0" /><button onClick={() => setValue(v => (typeof v === 'number' ? v + 1 : (Number(v) || 1)))} className="w-12 h-12 flex items-center justify-center bg-gray-100 rounded-xl text-2xl font-bold text-gray-600 shadow-sm">+</button></div></div>);
}

export function Timers() {
  const t = useTimer(); const exercises = useLiveQuery(() => db.exercises.toArray());
  return (
    <div className="p-4 pb-24 relative">
      {t.savedWorkoutData && (<div className="bg-blue-100 border border-blue-300 p-3 rounded-lg mb-4 flex justify-between items-center shadow-sm"><span className="font-bold text-blue-800 text-sm">Виконується: {t.activeName}</span><button onClick={t.clearActiveWorkout} className="text-blue-500 bg-white rounded-full p-2"><X size={16}/></button></div>)}
      <div className="flex bg-gray-200 rounded-lg p-1 mb-6"><button className={`flex-1 py-2 font-bold rounded-md ${t.mode === 'TABATA' ? 'bg-white shadow' : 'text-gray-500'}`} onClick={() => t.setMode('TABATA')}>Табата</button><button className={`flex-1 py-2 font-bold rounded-md ${t.mode === 'FREE' ? 'bg-white shadow' : 'text-gray-500'}`} onClick={() => t.setMode('FREE')}>Фактичний час</button></div>

      {t.mode === 'TABATA' ? (
        <div className="flex flex-col items-center">
          {!t.isRunning && t.phase === 'IDLE' && ( <div className="w-full bg-white p-4 rounded-xl shadow-sm mb-6 flex flex-col"><NumberControl label="Робота (сек)" value={t.workTime} setValue={t.setWorkTime} /><NumberControl label="Відпочинок (сек)" value={t.restTime} setValue={t.setRestTime} /><NumberControl label="Цикли" value={t.rounds} setValue={t.setRounds} /></div> )}
          <div className={`w-64 h-64 rounded-full flex flex-col items-center justify-center text-white shadow-lg transition-colors ${t.phase === 'PREP' ? 'bg-yellow-500' : t.phase === 'WORK' ? 'bg-red-500' : t.phase === 'REST' ? 'bg-green-500' : 'bg-gray-800'}`}><span className="text-2xl font-bold">{t.phase === 'PREP' ? 'ПІДГОТОВКА' : t.phase === 'WORK' ? 'РОБОТА' : t.phase === 'REST' ? 'ВІДПОЧИНОК' : 'ГОТОВИЙ'}</span><span className="text-7xl font-mono mt-2">{formatDuration(t.timeLeft)}</span>{t.phase !== 'IDLE' && t.phase !== 'PREP' && <span className="text-lg mt-2">Цикл {t.currentRound}/{Number(t.rounds) || 8}</span>}</div>
          <button onClick={t.toggleTabata} className="mt-10 bg-blue-600 text-white px-8 py-4 rounded-xl text-2xl font-bold w-full shadow-lg">{t.isRunning ? 'ПАУЗА' : t.phase === 'IDLE' ? 'СТАРТ' : 'ПРОДОВЖИТИ'}</button>
        </div>
      ) : (
        <div className="flex flex-col items-center w-full">
           <div className="text-6xl font-mono mt-4 mb-2">{formatDuration(t.freeTime)}</div><div className="text-lg font-bold mb-4 text-blue-600 uppercase">{t.freePhase}</div>
           <div className="w-full flex justify-between bg-white p-3 rounded-xl shadow-sm mb-4 border border-gray-100"><div className="text-center w-1/3"><div className="text-[10px] text-gray-400 font-bold uppercase">Розминка</div><div className={`font-mono text-lg ${t.freePhase === 'Розминка' ? 'text-yellow-500 font-bold' : 'text-gray-700'}`}>{formatDuration(t.phaseTimes.warmup)}</div></div><div className="text-center w-1/3 border-l border-r border-gray-100"><div className="text-[10px] text-gray-400 font-bold uppercase">Основна</div><div className={`font-mono text-lg ${t.freePhase === 'Основна' ? 'text-red-500 font-bold' : 'text-gray-700'}`}>{formatDuration(t.phaseTimes.main)}</div></div><div className="text-center w-1/3"><div className="text-[10px] text-gray-400 font-bold uppercase">Заминка</div><div className={`font-mono text-lg ${t.freePhase === 'Заминка' ? 'text-green-500 font-bold' : 'text-gray-700'}`}>{formatDuration(t.phaseTimes.cooldown)}</div></div></div>
           <div className="w-full bg-white p-4 rounded-xl shadow-sm mb-6 border border-gray-100"><NumberControl label="Відпочинок (сек)" value={t.freeRestTime} setValue={t.setFreeRestTime} /><div className="flex items-center justify-between mt-4"><div className={`text-4xl font-mono font-bold ${t.isFreeResting ? 'text-green-600' : 'text-gray-400'}`}>{t.isFreeResting ? formatDuration(t.freeRestTimeLeft) : formatDuration(Number(t.freeRestTime) || 60)}</div><button onClick={t.toggleFreeRest} className={`px-6 py-3 rounded-xl font-bold shadow-sm ${t.isFreeResting ? 'bg-red-500 text-white' : 'bg-blue-100 text-blue-700 active:bg-blue-200'}`}>{t.isFreeResting ? 'ЗУПИНИТИ' : 'СТАРТ ВІДПОЧИНКУ'}</button></div></div>
           <div className="grid grid-cols-1 gap-3 w-full"><button onClick={() => t.startFreePhase('Розминка')} className={`py-4 rounded-xl font-bold shadow-sm transition-colors ${t.freePhase === 'Розминка' ? 'bg-yellow-400 text-black ring-2 ring-yellow-500 ring-offset-2' : 'bg-gray-100 text-gray-600'}`}>Почати Розминку</button><button onClick={() => t.startFreePhase('Основна')} className={`py-4 rounded-xl font-bold shadow-sm transition-colors ${t.freePhase === 'Основна' ? 'bg-red-500 text-white ring-2 ring-red-500 ring-offset-2' : 'bg-gray-100 text-gray-600'}`}>Почати Основну</button><button onClick={() => t.startFreePhase('Заминка')} className={`py-4 rounded-xl font-bold shadow-sm transition-colors ${t.freePhase === 'Заминка' ? 'bg-green-500 text-white ring-2 ring-green-500 ring-offset-2' : 'bg-gray-100 text-gray-600'}`}>Почати Заминку</button><button onClick={t.initiateStopFreeWorkout} className="bg-gray-800 text-white py-4 rounded-xl font-bold mt-4 shadow-lg">{t.savedWorkoutData ? 'Завершити тренування' : 'Скинути таймер'}</button></div>
        </div>
      )}

      {t.showTimeEdit && t.savedWorkoutData && (
        <div className="fixed inset-0 bg-black/60 flex items-end justify-center z-[110] p-2 pb-16"><div className="bg-white w-full max-w-md rounded-2xl p-5 shadow-2xl max-h-[90vh] flex flex-col relative"><h3 className="font-bold text-xl mb-4 text-center">Підсумки тренування</h3>
            <div className="space-y-2 mb-6 shrink-0"><div className="flex justify-between p-2 bg-gray-50 rounded border"><span className="font-bold">Розминка</span><div className="flex gap-1"><input type="number" inputMode="decimal" value={t.editTimes.wm} onChange={e => t.setEditTimes({...t.editTimes, wm: Number(e.target.value)})} className="w-10 text-center border rounded"/>хв <input type="number" inputMode="decimal" value={t.editTimes.ws} onChange={e => t.setEditTimes({...t.editTimes, ws: Number(e.target.value)})} className="w-10 text-center border rounded"/>с</div></div><div className="flex justify-between p-2 bg-gray-50 rounded border"><span className="font-bold">Основна</span><div className="flex gap-1"><input type="number" inputMode="decimal" value={t.editTimes.mm} onChange={e => t.setEditTimes({...t.editTimes, mm: Number(e.target.value)})} className="w-10 text-center border rounded"/>хв <input type="number" inputMode="decimal" value={t.editTimes.ms} onChange={e => t.setEditTimes({...t.editTimes, ms: Number(e.target.value)})} className="w-10 text-center border rounded"/>с</div></div><div className="flex justify-between p-2 bg-gray-50 rounded border"><span className="font-bold">Заминка</span><div className="flex gap-1"><input type="number" inputMode="decimal" value={t.editTimes.cm} onChange={e => t.setEditTimes({...t.editTimes, cm: Number(e.target.value)})} className="w-10 text-center border rounded"/>хв <input type="number" inputMode="decimal" value={t.editTimes.cs} onChange={e => t.setEditTimes({...t.editTimes, cs: Number(e.target.value)})} className="w-10 text-center border rounded"/>с</div></div></div>
            <h4 className="font-bold text-sm text-gray-500 uppercase mb-2 shrink-0">Фактичні вправи</h4>
            <div className="flex-1 overflow-y-auto space-y-3 mb-4 border-t pt-2">
              {t.finishItems.map((item: any, idx: number) => { const exName = exercises?.find(e => e.id === item.exerciseId)?.name || 'Вправа'; return (<div key={idx} className="p-3 bg-white border rounded shadow-sm"><div className="flex justify-between mb-2"><span className="font-bold text-sm">{exName}</span><button onClick={() => { const n = t.finishItems.map((i:any)=>({...i})); n.splice(idx,1); t.setFinishItems(n); }} className="p-1 text-red-500"><Trash2 size={16}/></button></div><div className="flex gap-2"><input inputMode="decimal" value={item.weight} onChange={e => t.updateFinishItem(idx, 'weight', e.target.value)} placeholder="Вага" className="w-1/3 p-1 border rounded text-xs bg-gray-50" /><input inputMode="decimal" value={item.reps} onChange={e => t.updateFinishItem(idx, 'reps', e.target.value)} placeholder="Повтори" className="w-1/3 p-1 border rounded text-xs bg-gray-50" /><input value={item.band} onChange={e => t.updateFinishItem(idx, 'band', e.target.value)} placeholder="Еспандер" className="w-1/3 p-1 border rounded text-xs bg-gray-50" /></div></div>); })}
              <button onClick={() => { t.setShowFinishAddEx(true); t.setFinishExSearch(''); }} className="w-full py-3 bg-blue-50 text-blue-600 rounded-lg font-bold border border-dashed border-blue-300 flex justify-center items-center gap-2"><Plus size={18}/> Додати вправу</button>
            </div>
            <textarea value={t.workoutNote} onChange={e => t.setWorkoutNote(e.target.value)} placeholder="Примітка до тренування..." className="w-full p-3 border rounded-lg bg-gray-50 text-sm shadow-sm min-h-[60px] mb-4 shrink-0" />
            <div className="flex gap-3 shrink-0"><button onClick={() => t.setShowTimeEdit(false)} className="flex-1 bg-gray-100 text-gray-700 py-3 rounded-lg font-bold">Скасувати</button><button onClick={t.saveFinalFreeWorkout} className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-bold shadow-sm">Зберегти</button></div>

            {t.showFinishAddEx && (
              <div className="absolute inset-0 bg-white rounded-2xl flex flex-col p-4 z-20"><div className="flex justify-between items-center mb-4 border-b pb-2"><h3 className="font-bold">Оберіть вправу</h3><button onClick={() => t.setShowFinishAddEx(false)} className="p-2 text-gray-400 bg-gray-100 rounded-full"><X size={20}/></button></div><div className="relative mb-3"><Search className="absolute left-3 top-3 text-gray-400" size={18} /><input value={t.finishExSearch} onChange={e => t.setFinishExSearch(e.target.value)} placeholder="Пошук..." className="w-full p-2 pl-10 border rounded-lg bg-gray-50" /></div><div className="flex-1 overflow-y-auto space-y-2">{t.finishExSearch.trim() && !exercises?.some(e => e.name.toLowerCase() === t.finishExSearch.trim().toLowerCase()) && (<button onClick={async () => { const newId = generateId(); await db.exercises.add({ id: newId, name: t.finishExSearch.trim(), category: 'Користувацькі', muscle: 'Загальна' }); t.setFinishItems([...t.finishItems, { exerciseId: newId, weight: '', band: '', reps: '', note: '' }]); t.setShowFinishAddEx(false); t.setFinishExSearch(''); }} className="w-full text-left p-3 bg-blue-50 text-blue-700 border border-blue-200 rounded font-bold mb-2">+ Створити: "{t.finishExSearch.trim()}"</button>)}{exercises?.filter(ex => ex.name.toLowerCase().includes(t.finishExSearch.toLowerCase())).map(ex => (<button key={ex.id} onClick={() => { t.setFinishItems([...t.finishItems, { exerciseId: ex.id, weight: '', band: '', reps: '', note: '' }]); t.setShowFinishAddEx(false); }} className="w-full text-left p-3 bg-gray-50 border rounded font-medium">{ex.name}</button>))}</div></div>
            )}
          </div></div>
      )}
    </div>
  );
}

export function DataSync() {
  const exportData = async () => {
    const data = { exercises: await db.exercises.toArray(), workouts: await db.workouts.toArray(), scheduled: await db.scheduled.toArray(), history: await db.history.toArray() };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' }); const filename = `w_jornal_backup_${getLocalDateString(new Date())}.json`;
    if (navigator.share && navigator.canShare) { try { const file = new File([blob], filename, { type: 'application/json' }); if (navigator.canShare({ files: [file] })) { await navigator.share({ files: [file], title: 'Резервна копія' }); return; } } catch (err) {} }
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename; a.click();
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const text = event.target?.result as string; const data = JSON.parse(text);
        if (!data || typeof data !== 'object' || (!data.exercises && !data.workouts && !data.history && !data.scheduled)) { alert('Помилка: Файл не містить валідних даних.'); return; }
        if (!window.confirm('УВАГА! Всі поточні дані на телефоні будуть безповоротно замінені даними з файлу. Продовжити?')) return;
        await db.transaction('rw', db.exercises, db.workouts, db.scheduled, db.history, async () => { await db.exercises.clear(); await db.workouts.clear(); await db.scheduled.clear(); await db.history.clear(); if (data.exercises) await db.exercises.bulkAdd(data.exercises); if (data.workouts) await db.workouts.bulkAdd(data.workouts); if (data.scheduled) await db.scheduled.bulkAdd(data.scheduled); if (data.history) await db.history.bulkAdd(data.history); });
        alert('Дані успішно відновлено!'); window.location.reload();
      } catch (err) { alert('Помилка читання файлу.'); }
    }; reader.readAsText(file);
  };

  const clearPhone = async () => { if (window.confirm('УВАГА! Всі дані будуть ВИДАЛЕНІ. Ви точно зробили бекап?')) { await db.delete(); window.location.reload(); } };

  return (<div className="p-4 pb-24"><h2 className="text-2xl font-bold mb-6">Хмара / Дані</h2><div className="space-y-4"><div className="bg-white p-4 rounded-xl border shadow-sm"><h3 className="font-bold mb-2">Експорт (Бекап)</h3><button onClick={exportData} className="w-full bg-blue-600 text-white py-3 rounded-lg font-bold">Вивантажити дані</button></div><div className="bg-white p-4 rounded-xl border shadow-sm"><h3 className="font-bold mb-2">Відновлення з файлу</h3><input type="file" accept=".json" onChange={importData} className="w-full text-sm" /></div><div className="bg-red-50 p-4 rounded-xl border border-red-200 mt-8"><h3 className="font-bold text-red-700 mb-2">Небезпечна зона</h3><button onClick={clearPhone} className="w-full bg-red-600 text-white py-3 rounded-lg font-bold">Очистити телефон</button></div></div></div>);
}